"use client";

import * as React from "react";
import { motion } from "framer-motion";
import { cn } from "@/lib/utils";

export interface ContributionDay {
  date: string;
  count: number;
}

export interface GitHubContributionGraphProps
  extends React.HTMLAttributes<HTMLDivElement> {
  data?: ContributionDay[];
  weeks?: number;
  max?: number;
  cellSize?: number;
  gap?: number;
  showLabels?: boolean;
  animate?: boolean;
}

const DEFAULT_WEEKS = 52;

function getLevel(count: number, max: number) {
  if (count === 0) return 0;

  const ratio = count / Math.max(max, 1);

  if (ratio <= 0.25) return 1;
  if (ratio <= 0.5) return 2;
  if (ratio <= 0.75) return 3;

  return 4;
}

function generateDemoData(weeks: number): ContributionDay[] {
  const days = weeks * 7;
  const today = new Date();
  const data: ContributionDay[] = [];

  for (let i = days - 1; i >= 0; i--) {
    const date = new Date(today);
    date.setDate(today.getDate() - i);

    const random = Math.random();

    let count = 0;

    if (random > 0.35) {
      count = Math.floor(Math.random() * 12) + 1;
    }

    if (random > 0.9) {
      count += Math.floor(Math.random() * 20);
    }

    data.push({
      date: date.toISOString().split("T")[0],
      count,
    });
  }

  return data;
}

function formatDate(date: string) {
  return new Intl.DateTimeFormat("en", {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(new Date(`${ date } T00:00:00`));
}

export function GitHubContributionGraph({
  data,
  weeks = DEFAULT_WEEKS,
  max,
  cellSize = 12,
  gap = 3,
  showLabels = true,
  animate = true,
  className,
  ...props
}: GitHubContributionGraphProps) {
  const contributionData = React.useMemo(
    () => data ?? generateDemoData(weeks),
    [data, weeks],
  );

  const calculatedMax = React.useMemo(
    () =>
      max ??
      Math.max(
        ...contributionData.map((item) => item.count),
        1,
      ),
    [contributionData, max],
  );

  const columns = React.useMemo(() => {
    const result: ContributionDay[][] = [];

    for (let i = 0; i < contributionData.length; i += 7) {
      result.push(contributionData.slice(i, i + 7));
    }

    return result;
  }, [contributionData]);

  const totalContributions = contributionData.reduce(
    (total, day) => total + day.count,
    0,
  );

  return (
    <div
      className={cn(
        "w-full overflow-x-auto rounded-xl border bg-background p-5",
        className,
      )}
      {...props}
    >
      <div className="min-w-max">
        {showLabels && (
          <div className="mb-3 flex items-center justify-between">
            <div>
              <p className="text-sm font-medium">
                {totalContributions.toLocaleString()} contributions
              </p>

              <p className="text-xs text-muted-foreground">
                Last {weeks} weeks
              </p>
            </div>
          </div>
        )}

        <div className="flex">
          {/* Weekday labels */}
          {showLabels && (
            <div
              className="mr-2 flex flex-col text-[10px] text-muted-foreground"
              style={{ gap }}
            >
              <span style={{ height: cellSize }} />
              <span style={{ height: cellSize }}>Mon</span>
              <span style={{ height: cellSize }} />
              <span style={{ height: cellSize }}>Wed</span>
              <span style={{ height: cellSize }} />
              <span style={{ height: cellSize }}>Fri</span>
              <span style={{ height: cellSize }} />
            </div>
          )}

          {/* Contribution grid */}
          <div className="flex" style={{ gap }}>
            {columns.map((week, weekIndex) => (
              <div
                key={weekIndex}
                className="flex flex-col"
                style={{ gap }}
              >
                {week.map((day) => {
                  const level = getLevel(
                    day.count,
                    calculatedMax,
                  );

                  return (
                    <motion.div
                      key={day.date}
                      initial={
                        animate
                          ? {
                              opacity: 0,
                              scale: 0.7,
                            }
                          : false
                      }
                      animate={{
                        opacity: 1,
                        scale: 1,
                      }}
                      transition={{
                        duration: 0.2,
                        delay: animate
                          ? weekIndex * 0.008
                          : 0,
                      }}
                      className={cn(
                        "rounded-[3px] border border-black/5",
                        "dark:border-white/5",
                        "transition-transform duration-150",
                        "hover:scale-125 hover:z-10",
                        {
                          "bg-muted": level === 0,
                          "bg-emerald-200 dark:bg-emerald-950":
                            level === 1,
                          "bg-emerald-300 dark:bg-emerald-800":
                            level === 2,
                          "bg-emerald-500 dark:bg-emerald-600":
                            level === 3,
                          "bg-emerald-700 dark:bg-emerald-400":
                            level === 4,
                        },
                      )}
                      style={{
                        width: cellSize,
                        height: cellSize,
                      }}
                      title={`${ day.count } contributions on ${
  formatDate(
    day.date,
  )
} `}
                    />
                  );
                })}
              </div>
            ))}
          </div>
        </div>

        <div className="mt-4 flex items-center justify-end gap-2 text-xs text-muted-foreground">
          <span>Less</span>

          <div
            className="rounded-[3px] bg-muted"
            style={{
              width: cellSize,
              height: cellSize,
            }}
          />

          <div
            className="rounded-[3px] bg-emerald-200 dark:bg-emerald-950"
            style={{
              width: cellSize,
              height: cellSize,
            }}
          />

          <div
            className="rounded-[3px] bg-emerald-300 dark:bg-emerald-800"
            style={{
              width: cellSize,
              height: cellSize,
            }}
          />

          <div
            className="rounded-[3px] bg-emerald-500 dark:bg-emerald-600"
            style={{
              width: cellSize,
              height: cellSize,
            }}
          />

          <div
            className="rounded-[3px] bg-emerald-700 dark:bg-emerald-400"
            style={{
              width: cellSize,
              height: cellSize,
            }}
          />

          <span>More</span>
        </div>
      </div>
    </div>
  );
}

export default GitHubContributionGraph;
